// Apply the port to an official `vegaWebview` project, generated by the SDK.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
const here = path.dirname(fileURLToPath(import.meta.url));
const target = path.resolve(process.argv[2] || 'vega-build');
const manifest = path.join(target, 'manifest.toml');
if (!fs.existsSync(manifest) || !fs.existsSync(path.join(target, 'src/App.tsx'))) {
  throw new Error('Génère d’abord le modèle officiel vegaWebview, puis indique son dossier. Aucun fichier modifié.');
}
const assets = path.join(target, 'assets/canape');
fs.mkdirSync(assets, {recursive: true});
fs.cpSync(path.join(here, '../app'), assets, {recursive: true});
let html = fs.readFileSync(path.join(assets, 'index.html'), 'utf8');
html = html.replace(/\s*<!-- lecteur vidéo intégré[\s\S]*?<script src="\$WEBAPIS[^>]*><\/script>/, '');
html = html.replace('js/tizen.js', 'js/platform.js').replace(/\s*<script src="js\/avplay.js"><\/script>/, '');
html = html.replace('<script src="js/main.js">', '<script src="js/integration.js"></script>\n  <script src="js/main.js">');
fs.writeFileSync(path.join(assets, 'index.html'), html);
for (const name of ['platform.js', 'integration.js']) fs.copyFileSync(path.join(here, name), path.join(assets, 'js', name));
for (const name of ['tizen.js', 'avplay.js']) fs.rmSync(path.join(assets, 'js', name));
for (const name of ['App.tsx', 'network.js']) fs.copyFileSync(path.join(here, name), path.join(target, 'src', name));
const screens = path.join(assets, 'js/screens.js');
fs.writeFileSync(screens, fs.readFileSync(screens, 'utf8')
  .replace("'Service de la TV'", "'Connexion Fire TV'")
  .replace("'En cours de chargement'", "'XMLTV complet à porter ; guide Xtream disponible'"));
let toml = fs.readFileSync(manifest, 'utf8');
for (const id of ['com.amazon.webview.renderer_service', 'com.amazon.inputmethod.service', 'com.amazon.media.server',
  'com.amazon.mediametrics.service', 'com.amazon.mediabuffer.service', 'com.amazon.mediatransform.service',
  'com.amazon.audio.stream', 'com.amazon.audio.control', 'com.amazon.kepler.ucc.publisher', 'com.amazon.gipc.uuid.*']) {
  if (!toml.includes('id = "' + id + '"')) toml += '\n[[wants.service]]\nid = "' + id + '"\n';
}
// The generated template owns the native app entry point and packaging config.
// HTTPS only by default: HTTP providers require a domain-specific manifest policy.
fs.writeFileSync(manifest, toml);
console.log('Sources Canapé TV copiées dans ' + target + '. Lance npm install puis npm run build:app dans ce dossier.');
